 public static boolean valid(NativeGlassSettings value){if(value==null)return false;var g=value.glass();return GlassTextures.valid(g.shade)&&GlassTextures.validTint(g.tint)&&(g.material==-1||ModernFinishCatalog.validChoice(g.material))&&(g.layout==-1||TextureLayoutMode.valid(g.layout))&&g.size>=0&&g.size<=1&&g.panelFacing>=-1&&g.panelFacing<=3&&NativeWallEntity.valid(value.frames());}
