  if(previous!=null&&previous.valid)return previous.layouts.getOrDefault(pos.asLong(),NativePanelLayout.UNIT);if(previous!=null&&!previous.queued){previous.queued=true;for(long key:previous.layouts.keySet()){BlockPos next=BlockPos.of(key);if(NativeFluidWorld.loaded(level,next)&&level.getBlockEntity(next) instanceof NativeGlassEntity member)NativeFluidWorld.queue(member);}}
  var local=NativeGlassGroups.capture((x,y)->cell(level,pos.relative(right,x).above(y)),0,0,false);Map<Long,NativePanelLayout> world=new HashMap<>();for(var entry:local.entrySet()){long key=entry.getKey();world.put(pos.relative(right,(int)(key>>32)).above((int)key).asLong(),entry.getValue());}Group next=new Group(world);for(long key:world.keySet()){BlockPos memberPos=BlockPos.of(key);if(NativeFluidWorld.loaded(level,memberPos)&&level.getBlockEntity(memberPos) instanceof NativeGlassEntity member)member.group=next;}return next.layouts.getOrDefault(pos.asLong(),NativePanelLayout.UNIT);
