 private static boolean frameConnection(Level level,BlockPos owner,BlockState state,BlockPos next){Direction normal=canonicalFacing(state);for(int offset=-1;offset<=1;offset++){BlockPos candidate=next.relative(normal,offset);if(NativeFluidWorld.loaded(level,candidate)&&level.getBlockState(candidate).getBlock() instanceof NativeDiagonalWallBlock block&&!block.isPorthole()&&connects(level,owner,state,candidate))return true;}if(!NativeFluidWorld.loaded(level,next))return false;BlockState other=level.getBlockState(next);if(other.getBlock() instanceof NativeFlatWallBlock)return connects(level,owner,state,next);return state.is(other.getBlock())&&enabled(level,next)&&other.getValue(NativeGlassBlock.ROTATED).equals(state.getValue(NativeGlassBlock.ROTATED))&&other.getValue(NativeGlassBlock.DEPTH).equals(state.getValue(NativeGlassBlock.DEPTH));}
