 public static void refresh(NativeGlassEntity host){if(!NativeFluidWorld.installed(host))return;host.resolveSize();if(!host.available()){host.publishLocal(straight(host),false);return;}var state=host.getBlockState();var settings=host.settings();Direction face=facing(host);double near=nearAt(host.getLevel(),host.getBlockPos(),state);var corner=corner(host.getLevel(),host.getBlockPos(),state);var contact=corner==null?null:new NativeFlatGlassVisual.Contact(corner.frontArm,corner.backArm,corner.frontRight,corner.backRight,corner.straightLeft,corner.straightRight);Direction right=canonicalFacing(state).getClockWise();var visual=new NativeFlatGlassVisual(settings,new FlatGlassPolicy.Pose(state.getValue(NativeGlassBlock.ROTATED),state.getValue(NativeGlassBlock.DEPTH),settings.glass().size),layout(host),authored(host,corner),NativeGlassGroups.contour((x,y)->cell(host.getLevel(),host.getBlockPos().relative(right,x).above(y)),0,0),contact,face,near,false);var old=host.publication().geometry();var geometry=old.scalar().facing==face.get3DDataValue()&&old.scalar().near==near&&Objects.equals(host.visual().contact(),contact)?old:NativeGlassGeometry.build(face,near,corner);host.publishLocal(new NativeGlassEntity.Publication(settings,geometry,visual),false);}
